import type { FlagCode } from '@/i18n/routing';

/**
 * Micro flag: one empty element, drawn by app/flags.css (generated by scripts/build-flags.mjs from the art kept there). It used to be an
 * inline SVG of three to seven nodes per flag; with about 25 on the home page that was a quarter of the DOM and the cause of the long
 * "fonts changed" restyle, so the art moved into the stylesheet (docs/adr/0021-production-performance-and-enterprise-proof.md §3).
 * Not emoji: Windows ships no flag glyphs, so an emoji flag shows up there as two letters. Decorative: the language or the market is
 * always named in text beside it.
 */
export function Flag({ code, className }: { code: FlagCode; className?: string }) {
  return <span className={className ? `flag ${className}` : 'flag'} data-flag={code} aria-hidden="true" />;
}
